import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Risoluzione dei problemi","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/risoluzione-problemi.md","filePath":"user-guide/risoluzione-problemi.md"}'),r={name:"user-guide/risoluzione-problemi.md"};function l(n,e,s,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="risoluzione-dei-problemi" tabindex="-1">Risoluzione dei problemi <a class="header-anchor" href="#risoluzione-dei-problemi" aria-label="Permalink to &quot;Risoluzione dei problemi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Sintomo</th><th>Cosa controllare / cosa fare</th></tr></thead><tbody><tr><td>La ricerca non trova note che esistono</td><td>Palette comandi → <em>Ricostruisci indice</em>. L&#39;indice è locale e ricostruibile senza perdere nulla. La ricerca per sottostringa richiede almeno 3 caratteri.</td></tr><tr><td>Il login nel browser non torna all&#39;app</td><td>Verificate che l&#39;app sia ancora aperta; su Windows/Linux lo schema <code>clarae://</code> deve essere registrato (reinstallate se necessario). Potete forzare il ripiego con la variabile <code>CLARAE_AUTH_REDIRECT=scheme</code>.</td></tr><tr><td>All&#39;avvio un messaggio chiede di chiudere la vecchia app</td><td>La nuova versione deve spostare la cartella dati della 1.x e non può farlo mentre quella è aperta: chiudete la vecchia app e riavviate. Vedi <a href="./installazione.html#aggiornare-dalla-1x">Aggiornare dalla 1.x</a>.</td></tr><tr><td>Il workbench nel browser dice che un vault è già aperto in un&#39;altra scheda</td><td>Chiudete l&#39;altra scheda del workbench; dopo un aggiornamento dalla 1.x può essere rimasta aperta una scheda della versione precedente.</td></tr><tr><td>&quot;Account sospeso&quot; o la sincronizzazione si ferma</td><td>Il vostro account è stato sospeso dall&#39;amministratore: i dati locali sono intatti. Contattate l&#39;amministratore; riprenderà da solo dopo la riattivazione.</td></tr><tr><td>Dopo <em>Esci</em> il nuovo accesso non chiede la password</td><td>Con questa versione <em>Esci</em> chiude la sessione sul servizio di accesso e il login successivo chiede sempre le credenziali. Se non succede, avvisate chi amministra il cloud: può dipendere dalla configurazione del servizio di accesso (<a href="./../admin-guide/keycloak.html#controllare-un-realm-già-importato">guida</a>).</td></tr><tr><td>L&#39;elenco dei dispositivi ha più righe per lo stesso computer</td><td>Le versioni precedenti ne aggiungevano una a ogni accesso. L&#39;aggiornamento del cloud lascia attiva la più recente e revoca le altre; da ora lo stesso computer ha sempre la stessa riga. Se due computer hanno lo stesso nome diventano un solo dispositivo: rinominatene uno.</td></tr><tr><td>Nel vault c&#39;è ancora la cartella di configurazione della 1.x</td><td>È la cartella di configurazione che usava la 1.x (il nome è in <a href="./installazione.html#aggiornare-dalla-1x">Aggiornare dalla 1.x</a>). All&#39;apertura del vault, una volta per versione dell&#39;app, l&#39;app toglie ciò che <code>.clarae/</code> ha già; le impostazioni diverse vanno nel cestino del vault (<code>.trash/</code>). Per un vault collegato serve un cloud aggiornato alla 1.7 o successiva.</td></tr><tr><td>&quot;Quota esaurita&quot;</td><td>Le modifiche restano sul dispositivo. Liberate spazio (la quota conta solo i file correnti, non lo storico) o chiedete un aumento.</td></tr><tr><td>Un file è troppo grande per sincronizzarsi</td><td>C&#39;è un limite di dimensione per file stabilito dall&#39;amministratore; riducete il file o tenetelo fuori dal vault sincronizzato.</td></tr><tr><td>Compare una copia &quot;(conflitto …)&quot;</td><td>Due dispositivi hanno modificato lo stesso file. Aprite <em>Risolvi conflitti di sincronizzazione</em>, confrontate e tenete la versione giusta; nulla è andato perso.</td></tr><tr><td>La nota è cambiata su disco mentre la modificavo</td><td>Un altro programma ha modificato il file: scegliete <em>Ricarica</em> (vedete il nuovo contenuto) o <em>Sovrascrivi</em> (tenete il vostro). L&#39;app non sovrascrive da sola.</td></tr><tr><td>Ho cancellato una nota per errore</td><td><em>Recupera file eliminati</em>, oppure il cestino del sistema/del vault. Vedi <a href="./cronologia-recupero.html">Cronologia e recupero</a>.</td></tr><tr><td>Ho sbagliato a modificare una nota</td><td><em>Recupero file per questa nota</em> → scegliete una versione precedente → <em>Ripristina</em>.</td></tr><tr><td>Ho dimenticato la passphrase del vault privato</td><td>Sbloccate con la <strong>chiave di recupero</strong> e scegliete una nuova passphrase. Senza passphrase né chiave i dati non sono recuperabili da nessuno.</td></tr><tr><td>Il vault privato risulta &quot;Bloccato&quot; su un nuovo dispositivo</td><td>È normale: inserite la passphrase (o la chiave di recupero) con <em>Sblocca vault cifrato</em>.</td></tr><tr><td>Non posso condividere questo vault</td><td>I vault <strong>privati</strong> non sono condivisibili (per scelta, per la cifratura). Serve un vault condiviso.</td></tr><tr><td>Il download ZIP di un vault privato non parte</td><td>Si costruisce nel browser: serve la passphrase/chiave e una scheda aperta fino alla fine; vault molto grandi richiedono memoria e tempo.</td></tr><tr><td>Un disegno non si apre / appare vuoto offline</td><td>Gli asset sono inclusi nell&#39;app; se il problema persiste riavviate l&#39;app e segnalatelo con il file di log.</td></tr><tr><td>L&#39;app è lenta con un vault enorme</td><td>Chiudete il grafo globale (usate il grafo locale), evitate schede con basi molto grandi; l&#39;indice iniziale può richiedere tempo.</td></tr><tr><td>Un link non si risolve</td><td>Controllate maiuscole/spazi e il formato dei link in <em>Impostazioni → File e link</em>; i link non attraversano vault diversi.</td></tr></tbody></table><h2 id="dove-trovare-i-log-e-i-dati" tabindex="-1">Dove trovare i log e i dati <a class="header-anchor" href="#dove-trovare-i-log-e-i-dati" aria-label="Permalink to &quot;Dove trovare i log e i dati&quot;">​</a></h2><p>I log dell&#39;app sono in <code>logs/clarae.log</code> nella cartella dati (<em>Impostazioni → Informazioni</em> mostra il percorso; il file ruota a 10 MB). Contengono eventi tecnici e <strong>non</strong> il testo delle note. L&#39;invio automatico di crash report non è previsto in questa versione.</p><h2 id="segnalare-un-problema" tabindex="-1">Segnalare un problema <a class="header-anchor" href="#segnalare-un-problema" aria-label="Permalink to &quot;Segnalare un problema&quot;">​</a></h2><p>Indicate: versione (<em>Informazioni</em>), sistema operativo, cosa stavate facendo, e se possibile un estratto del log. Per i problemi del server, l&#39;amministratore consulta il <a href="./../admin-guide/runbook.html">runbook</a>.</p>',6)])])}const v=a(r,[["render",l]]);export{m as __pageData,v as default};
